INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱全昱", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“朱温在即位前更名晃”中为质问者。", "biography": null, "status": "draft", "id": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5"}, {"name": "朱友文", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“朱友文出任开封尹并主持建昌院”中为受命者。", "biography": null, "status": "draft", "id": "28293c54-1774-5e6d-b0a7-6ab233fcd5ec"}, {"name": "朱友珪", "aliases": ["郢王", "遥喜"], "era": "五代十国", "birth_year": null, "death_year": 913, "description": "朱温之子。912年参与弑父并即位，913年在禁军政变中身亡。", "biography": "朱温之子。912年参与弑父并即位，913年在禁军政变中身亡。", "status": "draft", "id": "eee69c6e-e547-574d-8e4a-8a627fad36d6"}, {"name": "朱友璋", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "biography": null, "status": "draft", "id": "831a530e-5f17-5fc8-bb0a-d5061e40196b"}, {"name": "朱友贞", "aliases": ["朱锽", "朱瑱", "均王", "梁末帝"], "era": "五代十国", "birth_year": null, "death_year": 923, "description": "后梁末帝。913年在大梁即位，923年唐军逼近时命皇甫麟杀死自己。", "biography": "后梁末帝。913年在大梁即位，923年唐军逼近时命皇甫麟杀死自己。", "status": "draft", "id": "592627e4-8841-5cca-a79b-782c37765037"}, {"name": "朱友雍", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "biography": null, "status": "draft", "id": "06b2387c-ba60-5cf4-888d-c776985ff0a0"}, {"name": "朱友徽", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封朱全昱及诸子为王”中为受封者。", "biography": null, "status": "draft", "id": "693e5819-f26f-5b23-92fa-3f3c6affcf33"}, {"name": "敬翔", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“敬翔主持崇政院，枢密院职事并入”中为受命者。", "biography": null, "status": "draft", "id": "2d3c796e-c064-52f4-90c8-1524b6b9f0c5"}]'::jsonb)
