INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "后梁封朱全昱及诸子为王", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月乙酉", "dynasty": "唐末五代十国", "description": "后梁封朱全昱为广王，朱友文为博王、朱友珪为郢王、朱友璋为福王、朱友贞为均王、朱友雍为贺王、朱友徽为建王；朱友文的养子身份另据前文记录。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "72c2f039-6e8c-5dd4-919d-18ea3dcb3d06"}, {"title": "后梁改东都旧第为建昌宫", "start_year": 907, "end_year": 907, "time_original": "907年五月辛卯", "dynasty": "唐", "description": "后梁改东都旧第为建昌宫。", "phases": [], "location_name": "东都旧第", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0df8939c-883e-5d1f-8b3c-91f6481c23b5"}, {"title": "梁军围攻潞州，晋军出兵救援", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月至六月条", "dynasty": "唐末五代十国", "description": "康怀贞奉命攻潞州；李嗣昭、李嗣弼守城。梁军久攻不克，转为筑垒围困；李克用命周德威等救援。这是907年围城与救援，与既有908年解围事件分别记录。", "phases": [], "location_name": "潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "0f2867e2-991b-5ba8-8507-ecf77ab7dc82"}, {"title": "后梁废枢密院并将其职事归崇政院", "start_year": 907, "end_year": 907, "time_original": "907年五月甲午", "dynasty": "唐", "description": "后梁废枢密院并将其职事归崇政院。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f8484d7a-ba86-55e2-882a-8737f19efc8e"}, {"title": "后梁勒令苏循、张祎等致仕", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月（干支原文作戊戍，待校）", "dynasty": "唐末五代十国", "description": "后梁勒令苏循、张祎等十五人致仕，将苏楷斥归田里；苏循父子后依朱友谦。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e82aad47-9dce-5ea9-a484-5c7f51434c0e"}, {"title": "卢约以处州归降吴越", "start_year": 907, "end_year": 907, "time_original": "907年五月条，具体日未载", "dynasty": "唐末五代十国", "description": "卢约以处州归降吴越。", "phases": [], "location_name": "处州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "4c289f76-c02b-53f6-b7e2-60fa9c8f0704"}, {"title": "楚军击败刘存等淮南水军，攻取岳州", "start_year": 907, "end_year": 907, "time_original": "907年五月出兵、六月交战", "dynasty": "唐末五代十国", "description": "杨渥遣刘存等攻楚；秦彦晖、黄璠合击淮南军，刘存、陈知新被俘后遭马殷处死，刘威退走。秦彦晖随后取岳州。", "phases": [], "location_name": "越堤、浏阳口、岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "237c5da4-1431-57f9-bbe6-7b4ac433142b"}, {"title": "张颢、徐温在败战后处死许玄应", "start_year": 907, "end_year": 907, "time_original": "907年六月败战后，具体日未载", "dynasty": "唐末五代十国", "description": "淮南军攻楚失败后，张颢、徐温收捕并处死弘农王腹心许玄应。与战场上处死刘存、陈知新分开记录。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "a7daea15-5d12-52ee-a826-02e35522ffd7"}, {"title": "楚军与彭玕进攻洪州未克", "start_year": 907, "end_year": 907, "time_original": "907年六月条，具体日未载", "dynasty": "唐末五代十国", "description": "马殷遣军与吉州刺史彭玕会攻洪州，未能攻克。", "phases": [], "location_name": "洪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "653874bc-a2b2-504c-a375-e81d566bfaf1"}, {"title": "范居实奉命救援泽州", "start_year": 907, "end_year": 907, "time_original": "梁开平元年六月条，具体日未载", "dynasty": "唐末五代十国", "description": "晋军攻泽州，后梁遣范居实领兵救援。", "phases": [], "location_name": "泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "d2f71797-3dcf-545a-93b6-b88d2cab065b"}, {"title": "韩建出任司徒、同平章事", "start_year": 907, "end_year": 907, "time_original": "梁开平元年六月甲寅", "dynasty": "唐末五代十国", "description": "后梁以平卢节度使韩建守司徒、同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e147b81c-4843-5ab2-af3e-f5ec7fc86954"}, {"title": "高季昌断粮击退雷彦恭与楚军", "start_year": 907, "end_year": 907, "time_original": "907年六月条，具体日未载", "dynasty": "唐末五代十国", "description": "雷彦恭与楚军进攻江陵，高季昌屯公安并切断对方粮道，雷彦恭败退，楚军亦退。", "phases": [], "location_name": "江陵、公安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "3d889160-d4c4-5d63-9a81-e1eaeb7214fb"}, {"title": "后梁授刘守光卢龙节度使", "start_year": 907, "end_year": 907, "time_original": "梁开平元年七月甲午", "dynasty": "唐末五代十国", "description": "刘守光囚父、自称留后后向后梁请命，获授卢龙节度使、同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e8178458-0df1-5659-bed2-a9a835faf195"}, {"title": "曲颢继曲裕为静海节度使", "start_year": 907, "end_year": 907, "time_original": "梁开平元年七月丙申", "dynasty": "唐末五代十国", "description": "曲裕死后，其子曲颢由权知留后受命为静海节度使。人名沿用《通鉴》记载，异名待考。", "phases": [], "location_name": "静海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "1a7cf851-fcd8-5ae7-81e7-ea7a251b80f3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "兄长", "description": "朱全昱为朱温兄长；见907年改名与封王记载。", "status": "draft", "id": "25262d71-7aa3-5bf2-b9a6-8a7a408ffca4", "person_a": "4a9e8e14-490e-5b74-945b-47e8c5c92bb5", "person_b": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"relation_type": "养父", "description": "朱温为朱友文养父；原文明确称养子，并说友文本康氏之子。907年受任及封王不改变养子属性。", "status": "draft", "id": "98103dc6-92bb-5e22-b001-4716a86a09d6", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "28293c54-1774-5e6d-b0a7-6ab233fcd5ec"}, {"relation_type": "父亲", "description": "朱温为朱友璋之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "dd8a50f5-c19c-5624-a90f-ed8dfeb194f9", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "831a530e-5f17-5fc8-bb0a-d5061e40196b"}, {"relation_type": "父亲", "description": "朱温为朱友雍之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "398d030b-70f8-5e77-9ffe-61d0bb92180e", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "06b2387c-ba60-5cf4-888d-c776985ff0a0"}, {"relation_type": "父亲", "description": "朱温为朱友徽之父。原文见907年条；不据此推导持续政治支持。", "status": "draft", "id": "591621df-2175-52e6-be08-000bde41b042", "person_a": "0555e455-34d4-54ef-b93e-b0e6425018ab", "person_b": "693e5819-f26f-5b23-92fa-3f3c6affcf33"}]'::jsonb)
